prompt_template.text:
敏感内容规则（知识库检索结果）：
{{#context#}}

素材内容：
{{#nodeStart.material#}}

请判断。

知识库检索结果（参考，冲突时以系统提示中的速查表为准）：
{{#context#}}

素材内容：
{{#nodeStart.material#}}

用户档位偏好：{{#nodeStart.level#}}

请输出分级 JSON。

data.code:
function main({ fact_text, grade_text, check_text, override_sensitive, avoid_words }) {
  /* 超纲词回灌通路（2026-09-20）：MAIN 图的 nodeClean 取自本图（FACT 版），
     而 4 个生成节点的提示词引用了 {{#nodeClean.avoid_a1#}} 这类变量 ——
     FACT 侧不补这段，MAIN 会因「变量不存在」跑不起来（重拼 MAIN 时静态校验抓到）。
     FACT 自身用不到 avoid_words（前端调 FACT 时不传），缺省按空处理，不影响抽取链路。
     容错原则与 GEN 侧一致：非 JSON / 缺字段 / 类型不对，一律当空，绝不抛错。 */
  let av = {};
  try { const o = JSON.parse(avoid_words || '{}'); if (o && typeof o === 'object') av = o; } catch (e) { }
  const fmtAvoid = (a) => (Array.isArray(a) && a.length)
    ? (a.join(', ') + '（共 ' + a.length + ' 个）')
    : '（本轮无 —— 上一稿本档已达标，请保持同样的用词水平）';
  /* ── 大意骨架统一（2026-09-20）─────────────────────────────────────
     4 档统一以 gist 的 12 条为段落骨架，facts 退化为「高档细节池」。
     事实卡的归属由 ① nodeFact 标注的 `gist` 字段给出（1–12），这里派生：
       gist_fact_map : 12 项，第 i 项 = 挂靠第 i 条大意的事实卡编号数组
       gist_lines    : 12 条大意的编号文本（给低档当段落骨架）
       level_material_b1 / _b2p : 大意骨架 + 每条下挂自己那些细节
     容错铁律（与全链路一致）：字段缺失 / 类型不对 → 一律降级为空，绝不抛错。 */
  const GN = 12;
  const buildGistSkeleton = (rawFact, fallbackText) => {
    const fo = (rawFact && typeof rawFact === 'object') ? rawFact : {};
    const fl = Array.isArray(fo.facts) ? fo.facts : [];
    const gl = Array.isArray(fo.gist) ? fo.gist : [];
    const txt = (x) => (typeof x === 'string' ? x : String((x && (x.en || x.zh)) || ''));
    const facts = fl.map((f) => ({
      en: String((f && f.en) || '').trim() || String((f && f.zh) || '').trim(),
      g: parseInt(f && f.gist, 10)
    })).filter((f) => f.en);
    /* 归属号纠偏：非整数 / 越界 / 缺省 → 按「已用最大号 + 1」顺序回填。
       绝不能因为模型漏标就把事实丢掉 —— 丢了细节，高档就写不出东西。 */
    let cursor = 1;
    facts.forEach((f) => {
      if (!(f.g >= 1 && f.g <= GN)) { f.g = cursor; }
      cursor = Math.max(cursor, f.g + 1);
    });
    /* 回填号越过 GN 时（模型**整体漏标**、而事实卡又多于 12 张）折回 1..GN 轮转。
       实测：14 张卡全部漏标 → 顺序回填成 1..14，第 13/14 张会因越界从骨架里消失。
       号溢出绝不能变成「事实卡被丢掉」。 */
    facts.forEach((f) => { if (f.g > GN) { f.g = ((f.g - 1) % GN) + 1; } });
    const map = [];
    for (let i = 1; i <= GN; i++) {
      map.push(facts.map((f, ix) => (f.g === i ? ix + 1 : 0)).filter(Boolean));
    }
    const gist = [];
    for (let i = 0; i < GN; i++) {
      const g = gl[i] || {};
      gist.push({ en: txt(g.en !== undefined ? g.en : g).trim(), zh: String((g && g.zh) || '').trim() });
    }
    /* 素材丢失兜底（只防事故，不改正常路径）：
       既没有 facts 也没有 gist 时（GEN 被单独调用、上游没传 facts_raw ——
       存量缓存里就有这种旧结果），若给了 fallbackText 就用它的编号行当骨架、
       高档材料退回该原文。绝不因为上游少传一个字段就让 B1/B2+「无米下锅」
       去凭空编内容 —— 那种塌陷没有任何报错，是最危险的一种。 */
    if (!facts.length && !gist.some((g) => g.en || g.zh)) {
      const rows = String(fallbackText || '').split(/\r?\n/)
        .map((s) => s.replace(/^\s*\d+\s*[.、)]\s*/, '').trim()).filter(Boolean);
      if (rows.length) {
        const fb = rows.join('\n');
        return {
          gist_fact_map: JSON.stringify(map),
          gist_lines: rows.map((t, ix) => (ix + 1) + '. ' + t).join('\n'),
          level_material_b1: fb,
          level_material_b2p: fb
        };
      }
    }
    const lines = [];
    for (let i = 1; i <= GN; i++) {
      lines.push('【大意 ' + i + '】' + (gist[i - 1].en || gist[i - 1].zh || '（本条无对应素材）'));
      map[i - 1].forEach((n) => lines.push('    细节：' + facts[n - 1].en));
    }
    const material = lines.join('\n');
    return {
      gist_fact_map: JSON.stringify(map),
      gist_lines: gist.map((g, i) => (i + 1) + '. ' + (g.en || g.zh)).join('\n'),
      level_material_b1: material,
      level_material_b2p: material
    };
  };
  const strip = (t) => String(t || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  const parseJSON = (t) => {
    const s = strip(t).replace(/```json|```/g, '');
    const m = s.match(/\{[\s\S]*\}/);
    if (m) {
      try { return JSON.parse(m[0]); } catch (e) {
        /* 尾逗号容错（与 GEN 聚合节点同一坑，见该处注释） */
        try { return JSON.parse(m[0].replace(/,(\s*[\]}])/g, '$1')); } catch (e2) { }
      }
    }
    return {};
  };
  const normLevel = (v) => {
    let s = String(v || '').trim().toUpperCase().replace(/\s+/g, '').replace(/[_-]/g, '.').replace(/档/g, '');
    s = s.replace(/^B2PLUS/, 'B2').replace(/^B2P/, 'B2');
    const AL = {
      'A1':'A1','A2':'A2','B1':'B1','B2':'B2',
      'A1.1':'A1','A1.2':'A1','A1.3':'A1',
      'A2.1':'A2','A2.2':'A2','A2.3':'A2',
      'B1.1':'B1','B1.2':'B1','B1.3':'B1',
      'B2.1':'B2','B2.2':'B2','B2.3':'B2',
      'B2+.1':'B2','B2+.2':'B2','B2+.3':'B2',
      'C1':'B2'
    };
    if (AL[s]) return AL[s];
    const m = s.match(/^(A1|A2|B1|B2\+?)/);
    if (m) { return m[1] === 'B2+' ? 'B2' : m[1]; }
    return 'B1';
  };
  const fact = parseJSON(fact_text);
  const GM = buildGistSkeleton(fact);
  const grade = parseJSON(grade_text);
  const check = parseJSON(check_text);
  const rawFacts = Array.isArray(fact.facts) ? fact.facts : [];
  const facts = rawFacts.map(f => {
    if (typeof f === 'string') return { en: f, zh: f };
    return { en: String((f && f.en) || '').trim(), zh: String((f && f.zh) || '').trim() };
  }).filter(f => f.en || f.zh);
  let sensLevel = String(check.level || 'S3').toUpperCase().trim();
  let sensAction = String(check.action || 'ok').toLowerCase().trim();
  let sensReason = String(check.reason || '');
  /* 人工放行：override_sensitive=true 时跳过敏感闸门（把 action/level 覆盖为通过），
     但把 AI 原始判定保留进 reason，供前端作警示留痕。 */
  const override = (override_sensitive === true || override_sensitive === 'true' ||
                    override_sensitive === '1' || override_sensitive === 1);
  if (override) {
    sensAction = 'ok';
    sensLevel = 'S3';
    sensReason = '人工放行（原判定：' + String(check.level || 'S3') + ' / ' + String(check.reason || '') + '）';
  }
  /* 分层大意基准（gist）：去数字、去专名的语义骨架，恰好 12 条。
     用途有二：① 供 A1/A2 低档生成（低档只讲大意拍）；② 作为全链路「主线是否走样」的比对基准。 */
  const rawGist = Array.isArray(fact.gist) ? fact.gist : [];
  const gist = rawGist.map(g => {
    if (typeof g === 'string') return { en: String(g).trim(), zh: String(g).trim() };
    return { en: String((g && g.en) || '').trim(), zh: String((g && g.zh) || '').trim() };
  }).filter(g => g.en || g.zh);

  /* 档位区间：由分级节点判出 lo / hi，这里只做归一化与顺序纠正。
     区间是**元数据**（前端据此限制档位控件范围），不改变「照常生成 12 档」。 */
  const ORD = { 'A1':1, 'A2':2, 'B1':3, 'B2':4 };
  let lvLo = normLevel(grade.lo || grade.level);
  /* hi 缺失时回退到 lo，而不是让 normLevel 的默认值（B1.1）把区间撑大 ——
     否则模型漏写 hi 会静默产出一个明显失真的区间。 */
  let lvHi = normLevel(grade.hi || grade.lo || grade.level);
  if (ORD[lvLo] > ORD[lvHi]) { const tmp = lvLo; lvLo = lvHi; lvHi = tmp; }
  let infoPoints = parseInt(grade.info_points, 10);
  if (!(infoPoints > 0)) infoPoints = facts.length;

  const lv = normLevel(grade.level);
  const big = lv;
  return {
    summary: fact.summary || fact.summary_en || '（未识别主题）',
    facts_text: facts.length ? facts.map((f, i) => (i + 1) + '. ' + (f.en || f.zh)).join('\n') : '（无）',
    gist: gist.length ? gist.map((g, i) => (i + 1) + '. ' + (g.en || g.zh)).join('\n') : '',
    gist_fact_map: GM.gist_fact_map,
    gist_lines: GM.gist_lines,
    level_material_b1: GM.level_material_b1,
    level_material_b2p: GM.level_material_b2p,
    level_lo: lvLo,
    level_hi: lvHi,
    info_points: String(infoPoints),
    level: lv,
    level_big: big,
    grade_reason: grade.reason || '',
    angle: grade.suggested_angle || '（无特殊角度）',
    sensitive: sensLevel + ' / ' + sensAction + ' / ' + sensReason,
    avoid_a1: fmtAvoid(av.A1), avoid_a2: fmtAvoid(av.A2),
    avoid_b1: fmtAvoid(av.B1), avoid_b2: fmtAvoid(av.B2),
    sens_level: sensLevel,
    sens_action: sensAction,
    sens_reason: sensReason,
    facts_json: JSON.stringify(facts),
    // facts_raw 必须是「干净 JSON」：硅基流动的模型默认会把思考过程写进 text，
    // 原样透传会让下游 GEN 多吞约 3.5 倍 token，前端也会读到思考文本。
    facts_raw: (function () {
      const s = strip(fact_text).replace(/```json|```/g, '');
      const m = s.match(/\{[\s\S]*\}/);
      return m ? m[0] : '';
    })()
  };
}
